4bool check_palindrome(string text) {
5
6    // if the string is empty or contains a single character,
7    // the string is a palindrome
8    if (text.empty() || text.length() == 1) {
9        return true;
10
11    }
12    
13    // check if the first and last characters are the same
14    if (text[0] == text[text.length() - 1]) {
15        return check_palindrome(text.substr(1, text.length() - 2));
16    }
17    else {
18        return false;
19    }
20}
